'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { FileTextIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import { AmountFilter } from './amount-filter';
import {
  INVOICES,
  STATUS_DETAILS,
  STATUS_FILTERS,
  WORKSPACE,
  type AmountRange,
  type Invoice,
  type StatusFilter,
} from './data';
import {
  CURRENCY_FORMAT,
  CURRENCY_LOCALE,
  FULL_RANGE,
  emptyLineOf,
  formatAmount,
  invoiceCountLabel,
  invoicesInRange,
  matchesStatus,
  totalOf,
} from './invoice-model';
import { useHeightPresence } from './motion-parts';

const LIST_SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

function isStatusFilter(value: unknown): value is StatusFilter {
  return STATUS_FILTERS.some((filter) => filter.id === value);
}

function InvoiceRow({ invoice }: { invoice: Invoice }) {
  const status = STATUS_DETAILS[invoice.status];

  return (
    <div className='flex h-14 items-center gap-3 px-4'>
      <span className='keycap-3d text-muted-foreground hidden size-8 shrink-0 items-center justify-center rounded-lg sm:flex'>
        <FileTextIcon />
      </span>
      <div className='min-w-0 flex-1'>
        <p className='truncate text-[13px] font-medium'>{invoice.client}</p>
        <p className='text-muted-foreground truncate text-xs tabular-nums'>
          {invoice.number} · {invoice.issuedOn}
        </p>
      </div>
      <div className='flex flex-col items-end gap-1 sm:flex-row-reverse sm:items-center sm:gap-4'>
        <span className='text-[13px] font-medium tabular-nums sm:w-20 sm:text-right'>
          {formatAmount(invoice.amount)}
        </span>
        <Chip color={status.color}>{status.label}</Chip>
      </div>
    </div>
  );
}

type NoMatchProps = {
  status: StatusFilter;
  range: AmountRange;
  onReset: () => void;
};

function NoMatch({ status, range, onReset }: NoMatchProps) {
  return (
    <div className='flex flex-col items-center px-6 py-10 text-center'>
      <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
        <FileTextIcon />
      </span>
      <p className='mt-4 text-sm font-medium'>Nothing matches these filters</p>
      <p className='text-muted-foreground mt-1 max-w-sm text-[13px] text-balance'>
        {emptyLineOf(status, range)}
      </p>
      <Button variant='outline' onClick={onReset} className='mt-4'>
        <XIcon />
        Reset filters
      </Button>
    </div>
  );
}

export default function Filters01() {
  const [status, setStatus] = useState<StatusFilter>('all');
  const [range, setRange] = useState<AmountRange>(FULL_RANGE);
  const heightPresence = useHeightPresence();
  const statusInvoices = INVOICES.filter((invoice) =>
    matchesStatus(invoice, status)
  );
  const shown = invoicesInRange(statusInvoices, range);
  const shownCount = shown.length;
  const shownTotal = totalOf(shown);
  const hasMatches = shownCount > 0;

  function pickStatus(value: unknown) {
    if (isStatusFilter(value)) {
      setStatus(value);
    }
  }

  function resetFilters() {
    setStatus('all');
    setRange(FULL_RANGE);
  }

  return (
    <div className='bg-background text-foreground min-h-dvh w-full'>
      <div className='mx-auto flex w-full max-w-3xl flex-col gap-4 px-4 py-6 md:px-6 md:py-10'>
        <header className='flex flex-wrap items-end justify-between gap-x-4 gap-y-1'>
          <div className='flex flex-col gap-0.5'>
            <h1 className='text-lg font-semibold text-balance'>
              {WORKSPACE.title}
            </h1>
            <p className='text-muted-foreground text-xs'>
              {WORKSPACE.period} · Illustrative figures
            </p>
          </div>
          <p className='text-muted-foreground text-[13px]'>
            <MotionNumber
              value={shownCount}
              className='text-foreground font-medium'
            />{' '}
            {invoiceCountLabel(shownCount)} ·{' '}
            <MotionNumber
              value={shownTotal}
              locale={CURRENCY_LOCALE}
              format={CURRENCY_FORMAT}
              className='text-foreground font-medium'
            />
          </p>
        </header>
        <div className='flex flex-wrap items-center gap-2'>
          <Tabs value={status} onValueChange={pickStatus}>
            <TabsList variant='segmented' aria-label='Status'>
              {STATUS_FILTERS.map((filter) => (
                <TabsTab key={filter.id} value={filter.id}>
                  {filter.label}
                </TabsTab>
              ))}
            </TabsList>
          </Tabs>
          <AmountFilter
            invoices={statusInvoices}
            value={range}
            onValueChange={setRange}
          />
        </div>
        <section aria-label='Matching invoices' className={LIST_SURFACE}>
          <ul className='max-h-[30rem] overflow-y-auto'>
            <AnimatePresence initial={false}>
              {shown.map((invoice) => (
                <motion.li
                  key={invoice.id}
                  {...heightPresence}
                  className='overflow-hidden'
                >
                  <InvoiceRow invoice={invoice} />
                </motion.li>
              ))}
            </AnimatePresence>
          </ul>
          <AnimatePresence initial={false}>
            {!hasMatches && (
              <motion.div
                key='no-match'
                {...heightPresence}
                className='overflow-hidden'
              >
                <NoMatch status={status} range={range} onReset={resetFilters} />
              </motion.div>
            )}
          </AnimatePresence>
        </section>
      </div>
    </div>
  );
}

'use client';

import { Slider as SliderPrimitive } from '@base-ui/react/slider';
import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { ChevronDownIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Popover,
  PopoverClose,
  PopoverContent,
  PopoverTitle,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

import {
  AMOUNT_BOUNDS,
  AMOUNT_PRESETS,
  type AmountPreset,
  type AmountRange,
  type Invoice,
} from './data';
import {
  CURRENCY_FORMAT,
  CURRENCY_LOCALE,
  FULL_RANGE,
  formatAmount,
  histogramOf,
  invoiceCountLabel,
  invoicesInRange,
  isFullRange,
  rangeLabelOf,
  sameRange,
  totalOf,
  type HistogramBin,
} from './invoice-model';

const THUMB_LABELS = ['Lowest amount', 'Highest amount'];

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const THUMB = [
  'group/thumb relative block size-4 shrink-0 rounded-full bg-white shadow-[0_1px_3px_rgb(0_0_0/0.18)] hairline-ring ring-foreground/15 outline-none',
  'transition-[scale,box-shadow] duration-150 ease-(--ease-out-strong) data-dragging:scale-110',
  'group-data-gliding/range:transition-[inset-inline-start,scale,box-shadow] group-data-gliding/range:duration-200',
  'has-focus-visible:ring-[3px] has-focus-visible:ring-ring/30',
].join(' ');

const INDICATOR = [
  'bg-primary rounded-full',
  'group-data-gliding/range:transition-[inset-inline-start,width] group-data-gliding/range:duration-200 group-data-gliding/range:ease-(--ease-out-strong)',
].join(' ');

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function rangeOf(value: number | readonly number[]): AmountRange {
  if (typeof value === 'number') {
    return [value, AMOUNT_BOUNDS.max];
  }
  return [value[0], value[1]];
}

function barHeightOf(bin: HistogramBin) {
  if (bin.count === 0) {
    return '2px';
  }
  const percent = Math.max(bin.share * 100, 8);
  return `${percent}%`;
}

function barToneOf(bin: HistogramBin) {
  if (bin.isInRange) {
    return 'bg-primary';
  }
  return 'bg-foreground/10';
}

function triggerLabelOf(range: AmountRange) {
  if (isFullRange(range)) {
    return 'Any amount';
  }
  return rangeLabelOf(range);
}

function amountAriaTextOf(_formatted: string, value: number) {
  return formatAmount(value);
}

function Histogram({ bins }: { bins: HistogramBin[] }) {
  return (
    <div aria-hidden='true' className='flex h-16 items-end gap-0.5'>
      {bins.map((bin) => (
        <span
          key={bin.id}
          style={{ height: barHeightOf(bin) }}
          className={cn(
            'flex-1 rounded-[3px] transition-colors duration-150',
            barToneOf(bin)
          )}
        />
      ))}
    </div>
  );
}

type RangeSliderProps = {
  value: AmountRange;
  isGliding: boolean;
  onValueChange: (range: AmountRange) => void;
  onValueCommitted: (range: AmountRange) => void;
};

/** Built from the Base UI parts so the thumbs and the fill can glide to a preset and still follow the pointer without lag. */
function RangeSlider({
  value,
  isGliding,
  onValueChange,
  onValueCommitted,
}: RangeSliderProps) {
  const glidingAttribute = isGliding || undefined;
  const minimumSteps = AMOUNT_BOUNDS.minGap / AMOUNT_BOUNDS.step;

  function changeRange(next: number | readonly number[]) {
    const range = rangeOf(next);
    onValueChange(range);
  }

  function commitRange(next: number | readonly number[]) {
    const range = rangeOf(next);
    onValueCommitted(range);
  }

  return (
    <SliderPrimitive.Root
      value={[value[0], value[1]]}
      min={AMOUNT_BOUNDS.min}
      max={AMOUNT_BOUNDS.max}
      step={AMOUNT_BOUNDS.step}
      minStepsBetweenValues={minimumSteps}
      onValueChange={changeRange}
      onValueCommitted={commitRange}
      data-gliding={glidingAttribute}
      className='group/range w-full'
    >
      <SliderPrimitive.Control className='relative flex w-full touch-none items-center py-2 select-none'>
        <SliderPrimitive.Track className='bg-foreground/10 relative h-1 w-full grow rounded-full'>
          <SliderPrimitive.Indicator className={INDICATOR} />
          {THUMB_LABELS.map((label, index) => (
            <SliderPrimitive.Thumb
              key={label}
              index={index}
              aria-label={label}
              getAriaValueText={amountAriaTextOf}
              className={THUMB}
            />
          ))}
        </SliderPrimitive.Track>
      </SliderPrimitive.Control>
    </SliderPrimitive.Root>
  );
}

type PresetListProps = {
  draft: AmountRange;
  onPick: (preset: AmountPreset) => void;
};

function PresetList({ draft, onPick }: PresetListProps) {
  return (
    <div
      role='group'
      aria-label='Common ranges'
      className='flex flex-wrap gap-1.5'
    >
      {AMOUNT_PRESETS.map((preset) => {
        const isCurrent = sameRange(preset.range, draft);

        return (
          <Button
            key={preset.id}
            variant='outline'
            size='sm'
            aria-pressed={isCurrent}
            onClick={() => onPick(preset)}
            className='aria-pressed:bg-primary/10 aria-pressed:text-primary-ink aria-pressed:ring-primary/30 dark:aria-pressed:bg-primary/15'
          >
            {preset.label}
          </Button>
        );
      })}
    </div>
  );
}

type AmountPanelProps = {
  invoices: Invoice[];
  value: AmountRange;
  onValueChange: (range: AmountRange) => void;
};

/** Mounted each time the popover opens, so the draft starts from the applied range. */
function AmountPanel({ invoices, value, onValueChange }: AmountPanelProps) {
  const [draft, setDraft] = useState<AmountRange>(value);
  const [isGliding, setIsGliding] = useState(false);
  const bins = histogramOf(invoices, draft);
  const matches = invoicesInRange(invoices, draft);
  const matchCount = matches.length;
  const matchTotal = totalOf(matches);
  const countNoun = invoiceCountLabel(matchCount);
  const isReset = isFullRange(draft);

  function followPointer(range: AmountRange) {
    setIsGliding(false);
    setDraft(range);
  }

  function jumpTo(range: AmountRange) {
    setIsGliding(true);
    setDraft(range);
    onValueChange(range);
  }

  return (
    <div className='flex flex-col gap-4'>
      <div className='flex items-baseline justify-between gap-3'>
        <PopoverTitle>Amount</PopoverTitle>
        <span className='text-muted-foreground text-xs tabular-nums'>
          {rangeLabelOf(draft)}
        </span>
      </div>
      <div className='flex flex-col gap-1'>
        <Histogram bins={bins} />
        <RangeSlider
          value={draft}
          isGliding={isGliding}
          onValueChange={followPointer}
          onValueCommitted={onValueChange}
        />
        <div className='text-muted-foreground flex justify-between text-xs tabular-nums'>
          <span>{formatAmount(AMOUNT_BOUNDS.min)}</span>
          <span>{formatAmount(AMOUNT_BOUNDS.max)}</span>
        </div>
      </div>
      <PresetList draft={draft} onPick={(preset) => jumpTo(preset.range)} />
      <div className='flex items-center gap-2 pt-1'>
        <p className='text-muted-foreground min-w-0 flex-1 truncate text-xs'>
          <MotionNumber
            value={matchCount}
            className='text-foreground font-medium'
          />{' '}
          {countNoun} ·{' '}
          <MotionNumber
            value={matchTotal}
            locale={CURRENCY_LOCALE}
            format={CURRENCY_FORMAT}
          />
        </p>
        <Button
          variant='ghost'
          size='sm'
          disabled={isReset}
          onClick={() => jumpTo(FULL_RANGE)}
        >
          Reset
        </Button>
        <PopoverClose render={<Button size='sm' />}>Done</PopoverClose>
      </div>
    </div>
  );
}

type AmountFilterProps = {
  /** The invoices left by the other filters: the histogram draws their spread. */
  invoices: Invoice[];
  value: AmountRange;
  onValueChange: (range: AmountRange) => void;
};

export function AmountFilter({
  invoices,
  value,
  onValueChange,
}: AmountFilterProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const label = triggerLabelOf(value);
  const isFiltered = !isFullRange(value);

  return (
    <div className='flex items-center gap-1'>
      <Popover>
        <PopoverTrigger
          render={<Button variant='outline' className='gap-1.5 pe-2.5' />}
        >
          <span className='text-muted-foreground'>Amount</span>
          <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
            <AnimatePresence mode='popLayout' initial={false}>
              <motion.span
                key={label}
                variants={variants}
                initial='enter'
                animate='visible'
                exit='exit'
                transition={SWAP_TRANSITION}
                className='tabular-nums'
              >
                {label}
              </motion.span>
            </AnimatePresence>
          </AnimatedSize>
          <ChevronDownIcon className='text-muted-foreground size-3.5' />
        </PopoverTrigger>
        <PopoverContent align='start' className='w-80'>
          <AmountPanel
            invoices={invoices}
            value={value}
            onValueChange={onValueChange}
          />
        </PopoverContent>
      </Popover>
      <AnimatePresence initial={false}>
        {isFiltered && (
          <motion.span
            key='clear-amount'
            variants={variants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={SWAP_TRANSITION}
            className='flex'
          >
            <Button
              variant='ghost'
              size='icon-sm'
              aria-label='Clear the amount filter'
              onClick={() => onValueChange(FULL_RANGE)}
              className='rounded-full'
            >
              <XIcon />
            </Button>
          </motion.span>
        )}
      </AnimatePresence>
    </div>
  );
}

import {
  AMOUNT_BOUNDS,
  HISTOGRAM_BIN_COUNT,
  type AmountRange,
  type Invoice,
  type StatusFilter,
  WORKSPACE,
} from './data';

export type HistogramBin = {
  id: string;
  count: number;
  /** Share of the tallest bin, from 0 to 1. */
  share: number;
  isInRange: boolean;
};

export const FULL_RANGE: AmountRange = [AMOUNT_BOUNDS.min, AMOUNT_BOUNDS.max];

export const CURRENCY_LOCALE = 'en-IE';

export const CURRENCY_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'EUR',
  maximumFractionDigits: 0,
};

const CURRENCY = new Intl.NumberFormat(CURRENCY_LOCALE, CURRENCY_FORMAT);

export function formatAmount(amount: number) {
  return CURRENCY.format(amount);
}

export function isFullRange(range: AmountRange) {
  const startsAtMinimum = range[0] === AMOUNT_BOUNDS.min;
  const endsAtMaximum = range[1] === AMOUNT_BOUNDS.max;
  return startsAtMinimum && endsAtMaximum;
}

export function sameRange(first: AmountRange, second: AmountRange) {
  const sameStart = first[0] === second[0];
  const sameEnd = first[1] === second[1];
  return sameStart && sameEnd;
}

export function rangeLabelOf(range: AmountRange) {
  if (range[1] === AMOUNT_BOUNDS.max) {
    return `${formatAmount(range[0])} and over`;
  }
  if (range[0] === AMOUNT_BOUNDS.min) {
    return `Up to ${formatAmount(range[1])}`;
  }
  return `${formatAmount(range[0])} – ${formatAmount(range[1])}`;
}

export function matchesStatus(invoice: Invoice, status: StatusFilter) {
  if (status === 'all') {
    return true;
  }
  return invoice.status === status;
}

export function isInRange(amount: number, range: AmountRange) {
  const isAboveStart = amount >= range[0];
  const isBelowEnd = amount <= range[1];
  return isAboveStart && isBelowEnd;
}

export function invoicesInRange(invoices: Invoice[], range: AmountRange) {
  return invoices.filter((invoice) => isInRange(invoice.amount, range));
}

export function totalOf(invoices: Invoice[]) {
  let total = 0;
  for (const invoice of invoices) {
    total += invoice.amount;
  }
  return total;
}

export function invoiceCountLabel(count: number) {
  if (count === 1) {
    return 'invoice';
  }
  return 'invoices';
}

function binIndexOf(amount: number, binWidth: number) {
  const index = Math.floor((amount - AMOUNT_BOUNDS.min) / binWidth);
  return Math.min(index, HISTOGRAM_BIN_COUNT - 1);
}

function tallestOf(counts: number[]) {
  const tallest = Math.max(...counts);
  return Math.max(tallest, 1);
}

/** A bin lights up when its middle sits inside the range, so a thumb dragged across a bin flips it once. */
export function histogramOf(invoices: Invoice[], range: AmountRange) {
  const span = AMOUNT_BOUNDS.max - AMOUNT_BOUNDS.min;
  const binWidth = span / HISTOGRAM_BIN_COUNT;
  const counts: number[] = Array.from({ length: HISTOGRAM_BIN_COUNT }, () => 0);
  for (const invoice of invoices) {
    const index = binIndexOf(invoice.amount, binWidth);
    counts[index] += 1;
  }
  const tallest = tallestOf(counts);
  const bins: HistogramBin[] = counts.map((count, index) => {
    const middle = AMOUNT_BOUNDS.min + binWidth * (index + 0.5);
    return {
      id: `bin-${index}`,
      count,
      share: count / tallest,
      isInRange: isInRange(middle, range),
    };
  });
  return bins;
}

function statusPhraseOf(status: StatusFilter) {
  if (status === 'all') {
    return 'No invoice';
  }
  return `No ${status} invoice`;
}

function rangePhraseOf(range: AmountRange) {
  const start = formatAmount(range[0]);
  const end = formatAmount(range[1]);
  if (range[1] === AMOUNT_BOUNDS.max) {
    return `of ${start} or more`;
  }
  if (range[0] === AMOUNT_BOUNDS.min) {
    return `up to ${end}`;
  }
  return `between ${start} and ${end}`;
}

export function emptyLineOf(status: StatusFilter, range: AmountRange) {
  const subject = statusPhraseOf(status);
  if (isFullRange(range)) {
    return `${subject} in ${WORKSPACE.period}`;
  }
  const rangePhrase = rangePhraseOf(range);
  return `${subject} ${rangePhrase}`;
}

'use client';

import { type MotionProps, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

const EASE_OUT_STRONG: [number, number, number, number] = [0.23, 1, 0.32, 1];

const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.14, ease: EASE_OUT_STRONG };

type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

export const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that join or leave a list open and close their own height, so what follows slides. */
export function useHeightPresence() {
  const shouldReduceMotion = usePrefersReducedMotion();
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

export type InvoiceStatus = 'paid' | 'open' | 'overdue';

export type StatusFilter = 'all' | InvoiceStatus;

export type Invoice = {
  id: string;
  number: string;
  client: string;
  issuedOn: string;
  amount: number;
  status: InvoiceStatus;
};

export type AmountRange = readonly [number, number];

export type AmountPreset = {
  id: string;
  label: string;
  range: AmountRange;
};

export const WORKSPACE = {
  title: 'Invoices',
  period: 'September and October',
};

export const AMOUNT_BOUNDS = {
  min: 0,
  max: 6000,
  step: 50,
  /** The two thumbs never come closer than this, so a range always holds something. */
  minGap: 250,
};

export const HISTOGRAM_BIN_COUNT = 24;

export const STATUS_FILTERS: { id: StatusFilter; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'paid', label: 'Paid' },
  { id: 'open', label: 'Open' },
  { id: 'overdue', label: 'Overdue' },
];

export const STATUS_DETAILS: Record<
  InvoiceStatus,
  { label: string; color: string }
> = {
  paid: { label: 'Paid', color: 'var(--success)' },
  open: { label: 'Open', color: 'var(--info)' },
  overdue: { label: 'Overdue', color: 'var(--destructive)' },
};

export const AMOUNT_PRESETS: AmountPreset[] = [
